# ! [doc = " Random data generation with the Linux kernel."] # ! [doc = ""] # ! [doc = " The first interface random data interface to be introduced on Linux were"] # ! [doc = " the `/dev/random` and `/dev/urandom` special files. As paths can become"] # ! [doc = " unreachable when inside a chroot and when the file descriptors are exhausted,"] # ! [doc = " this was not enough to provide userspace with a reliable source of randomness,"] # ! [doc = " so when the OpenBSD 5.6 introduced the `getentropy` syscall, Linux 3.17 got"] # ! [doc = " its very own `getrandom`  syscall to match.[^1] Unfortunately, even if our"] # ! [doc = " minimum supported version were high enough, we still couldn't rely on the"] # ! [doc = " syscall being available, as it is blocked in `seccomp` by default."] # ! [doc = ""] # ! [doc = " The question is therefore which of the random sources to use. Historically,"] # ! [doc = " the kernel contained two pools: the blocking and non-blocking pool. The"] # ! [doc = " blocking pool used entropy estimation to limit the amount of available"] # ! [doc = " bytes, while the non-blocking pool, once initialized using the blocking"] # ! [doc = " pool, uses a CPRNG to return an unlimited number of random bytes. With a"] # ! [doc = " strong enough CPRNG however, the entropy estimation didn't contribute that"] # ! [doc = " much towards security while being an excellent vector for DoS attacks. Thus,"] # ! [doc = " the blocking pool was removed in kernel version 5.6.[^2] That patch did not"] # ! [doc = " magically increase the quality of the non-blocking pool, however, so we can"] # ! [doc = " safely consider it strong enough even in older kernel versions and use it"] # ! [doc = " unconditionally."] # ! [doc = ""] # ! [doc = " One additional consideration to make is that the non-blocking pool is not"] # ! [doc = " always initialized during early boot. We want the best quality of randomness"] # ! [doc = " for the output of `DefaultRandomSource` so we simply wait until it is"] # ! [doc = " initialized. When `HashMap` keys however, this represents a potential source"] # ! [doc = " of deadlocks, as the additional entropy may only be generated once the"] # ! [doc = " program makes forward progress. In that case, we just use the best random"] # ! [doc = " data the system has available at the time."] # ! [doc = ""] # ! [doc = " So in conclusion, we always want the output of the non-blocking pool, but"] # ! [doc = " may need to wait until it is initialized. The default behavior of `getrandom`"] # ! [doc = " is to wait until the non-blocking pool is initialized and then draw from there,"] # ! [doc = " so if `getrandom` is available, we use its default to generate the bytes. For"] # ! [doc = " `HashMap`, however, we need to specify the `GRND_INSECURE` flags, but that"] # ! [doc = " is only available starting with kernel version 5.6. Thus, if we detect that"] # ! [doc = " the flag is unsupported, we try `GRND_NONBLOCK` instead, which will only"] # ! [doc = " succeed if the pool is initialized. If it isn't, we fall back to the file"] # ! [doc = " access method."] # ! [doc = ""] # ! [doc = " The behavior of `/dev/urandom` is inverse to that of `getrandom`: it always"] # ! [doc = " yields data, even when the pool is not initialized. For generating `HashMap`"] # ! [doc = " keys, this is not important, so we can use it directly. For secure data"] # ! [doc = " however, we need to wait until initialization, which we can do by `poll`ing"] # ! [doc = " `/dev/random`."] # ! [doc = ""] # ! [doc = " TLDR: our fallback strategies are:"] # ! [doc = ""] # ! [doc = " Secure data                                 | `HashMap` keys"] # ! [doc = " --------------------------------------------|------------------"] # ! [doc = " getrandom(0)                                | getrandom(GRND_INSECURE)"] # ! [doc = " poll(\"/dev/random\") && read(\"/dev/urandom\") | getrandom(GRND_NONBLOCK)"] # ! [doc = "                                             | read(\"/dev/urandom\")"] # ! [doc = ""] # ! [doc = " [^1]: <https://lwn.net/Articles/606141/>"] # ! [doc = " [^2]: <https://lwn.net/Articles/808575/>"] # ! [doc = ""] use split_decls_genesis :: ourprelude :: * ; use crate :: fs :: File ; use crate :: io :: Read ; use crate :: os :: fd :: AsRawFd ; use crate :: sync :: OnceLock ; use crate :: sync :: atomic :: Ordering :: { Acquire , Relaxed , Release } ; use crate :: sync :: atomic :: { Atomic , AtomicBool } ; use crate :: sys :: pal :: os :: errno ; use crate :: sys :: pal :: weak :: syscall ; fn getrandom (mut bytes : & mut [u8] , insecure : bool) { syscall ! (fn getrandom (buffer : * mut libc :: c_void , length : libc :: size_t , flags : libc :: c_uint ,) -> libc :: ssize_t ;) ; static GETRANDOM_AVAILABLE : Atomic < bool > = AtomicBool :: new (true) ; static GRND_INSECURE_AVAILABLE : Atomic < bool > = AtomicBool :: new (true) ; static URANDOM_READY : Atomic < bool > = AtomicBool :: new (false) ; static DEVICE : OnceLock < File > = OnceLock :: new () ; if GETRANDOM_AVAILABLE . load (Relaxed) { loop { if bytes . is_empty () { return ; } let flags = if insecure { if GRND_INSECURE_AVAILABLE . load (Relaxed) { libc :: GRND_INSECURE } else { libc :: GRND_NONBLOCK } } else { 0 } ; let ret = unsafe { getrandom (bytes . as_mut_ptr () . cast () , bytes . len () , flags) } ; if ret != - 1 { bytes = & mut bytes [ret as usize ..] ; } else { match errno () { libc :: EINTR => continue , libc :: EINVAL if flags == libc :: GRND_INSECURE => { GRND_INSECURE_AVAILABLE . store (false , Relaxed) ; continue ; } libc :: EAGAIN if flags == libc :: GRND_NONBLOCK => break , libc :: ENOSYS | libc :: EPERM => { GETRANDOM_AVAILABLE . store (false , Relaxed) ; break ; } _ => panic ! ("failed to generate random data") , } } } } if ! insecure { if ! URANDOM_READY . load (Acquire) { let random = File :: open ("/dev/random") . expect ("failed to open /dev/random") ; let mut fd = libc :: pollfd { fd : random . as_raw_fd () , events : libc :: POLLIN , revents : 0 } ; while ! URANDOM_READY . load (Acquire) { let ret = unsafe { libc :: poll (& mut fd , 1 , - 1) } ; match ret { 1 => { assert_eq ! (fd . revents , libc :: POLLIN) ; URANDOM_READY . store (true , Release) ; break ; } - 1 if errno () == libc :: EINTR => continue , _ => panic ! ("poll(\"/dev/random\") failed") , } } } } DEVICE . get_or_try_init (| | File :: open ("/dev/urandom")) . and_then (| mut dev | dev . read_exact (bytes)) . expect ("failed to generate random data") ; } pub fn fill_bytes (bytes : & mut [u8]) { getrandom (bytes , false) ; } pub fn hashmap_random_keys () -> (u64 , u64) { let mut bytes = [0 ; 16] ; getrandom (& mut bytes , true) ; let k1 = u64 :: from_ne_bytes (bytes [.. 8] . try_into () . unwrap ()) ; let k2 = u64 :: from_ne_bytes (bytes [8 ..] . try_into () . unwrap ()) ; (k1 , k2) }